const D = { scale:1, energy:.7, hue:120, speed:1, density:.5, x:.3, y:.8, pose:'hop', style:'xray', act:'pond', seed:0, limb:.5, chub:.5, bulge:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), ez=t=>{t=clp(t,0,1);return t*t*(3-2*t);};
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const sn=(tt,off)=>{const f=Math.floor(tt),xq=tt-f;return (fr(f+off)*(1-xq)+fr(f+1+off)*xq-.5)*2;};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const u=Math.min(width,height), sc=u*P.scale/320;
const bt=K.beat*P.speed, sub=frc(bt);
const kick=K.pulse*.6 + A.bass*.9;
const air=A.treble*.7;
const en=P.energy*(.45+.55*K.intensity);
const H=md(P.hue,360);
const style=P.style, xray=style==='xray', toxic=style==='toxic', lino=style==='lino', wire=style==='wire', swamp=style==='swamp';
const chub=.72+P.chub*.66, LL=.7+P.limb*.7, BUL=.7+P.bulge*.8;

// dramaturgy
let croakE=.5, restlessness=.5, dir=1;
if(P.act==='pond'){ croakE=.4+.5*K.intensity; restlessness=.3+.4*Math.abs(sn(K.t*.06,4)); }
else if(P.act==='rain'){ croakE=.8+.2*K.intensity; restlessness=.7; }
else if(P.act==='dusk'){ croakE=.3+.2*Math.sin(K.section*.9); restlessness=.15+.3*K.intensity; }
dir = sn(Math.floor(K.beat/8),5)>0?1:-1;

// throat sac inflation: baseline pumps every beat
const croak = clp(K.swell*.6 + kick*.5, 0, 1) * croakE;

// pose motion
let riseY=0, stretch=0, legExt=0, sqx=1, sqy=1, glideX=0, tilt=0;
const pose=P.pose;
if(pose==='ribbit'){ const p=kick; riseY=-p*.03; sqx=1+croak*.06; sqy=1-croak*.05; tilt=Math.sin(bt*Math.PI)*.02; }
else if(pose==='swim'){ const g=frc(bt*.5); legExt=Math.max(0,Math.sin(g*Math.PI*2))*LL; glideX=Math.sin(bt*Math.PI*.5)*.12*en*dir; riseY=Math.sin(bt*Math.PI)*.02; tilt=.05*dir; }
else if(pose==='idle'){ riseY=K.swell*.02*en; sqy=1+K.swell*.03; tilt=Math.sin(bt*Math.PI)*.015; }
else { // hop (default): load then leap across one bar (2 beats)
  const c=frc(bt*.5);
  const load=c<.4?ez(c/.4):(c<.5?1:0);
  const fly=c>=.5?ez((c-.5)/.5):0;
  const arc=Math.sin(fly*Math.PI);
  riseY = -arc*.34*en - load*.03;
  glideX = fly*.18*en*dir;
  legExt = fly*LL;
  stretch = fly*.4;
  sqx = 1+load*.12-fly*.14; sqy = 1-load*.1+fly*.16;
  tilt = fly*.25*dir;
}

const cx=P.x*width + glideX*width*.5, gy=P.y*height + riseY*260*sc;

function skin(l, sat, al){
  if(wire){ noFill(); return; }
  if(xray){ noStroke(); fill(md(H+6,360), 30+30*sat, 22+l*40, (al==null?26:al)); return; }
  if(toxic){ noStroke(); fill(md(H+ l*40,360), 85, 40+l*55); return; }
  if(lino){ noStroke(); fill(md(H,360), l>.55?20:70, l>.55?92:22); return; }
  if(swamp){ noStroke(); const lit=clp(l,0,1); fill(md(H+(lit-.5)*25,360), 45, 6+lit*70); return; }
  noStroke(); fill(H,70,30+l*55);
}
function edge(w,l){ if(wire){ stroke(md(H+4,360),50,95,88); strokeWeight(w); } else if(lino){ stroke(md(H,360),80,10); strokeWeight(w); } else if(xray){ stroke(md(H+10,360),40,80,55); strokeWeight(w*.7); } else noStroke(); }

// stipple cache for toxic
if(toxic){ if(!S.dotKey||S.dotKey!==Math.round(u)+'_'+P.seed){ S.dotKey=Math.round(u)+'_'+P.seed; const bs=Math.max(64,Math.round(u*.55)); const g=createGraphics(bs,bs); g.noStroke(); g.colorMode(HSB,360,100,100,100); for(let i=0;i<260;i++){ const x=fr(i*3.1)*bs, y=fr(i*5.7)*bs, r=(.5+fr(i*8.3)*1.8); g.fill(md(H+180,360),90,95,70); g.circle(x,y,r);} S.dot=g; } }

push();
translate(cx, gy);
rotate(tilt);
scale(sqx, sqy);
if(swamp){ drawingContext.shadowColor='hsba('+md(H,360)+',60%,50%,0.85)'; drawingContext.shadowBlur=26*sc; }
if(xray){ drawingContext.shadowColor='hsba('+md(H+10,360)+',70%,70%,0.7)'; drawingContext.shadowBlur=20*sc; }
const s=sc;

// ===== HIND LEGS (folded Z, extend on leap) =====
for(const sgn of [-1,1]){ push();
  translate(sgn*52*s*chub, 8*s);
  // thigh
  push(); rotate(sgn*(0.7 - legExt*0.9)); skin(.3,1); edge(1.2*s); ellipse(sgn*20*s, 8*s, 34*s*chub, 20*s); pop();
  // shin extends
  push(); translate(sgn*(30+legExt*40)*s, (18-legExt*6)*s); rotate(sgn*(-0.9 + legExt*1.4)); skin(.34,1); edge(1.1*s); ellipse(sgn*16*s,0, 30*s, 15*s*LL);
    // webbed foot
    skin(.4,.6); const fx=sgn*(30+legExt*10)*s; beginShape(); vertex(fx,-6*s); for(let k=-2;k<=2;k++){ vertex(fx+sgn*(10+Math.abs(k)*3)*s, k*7*s);} vertex(fx,6*s); endShape(CLOSE); pop();
pop(); }

// ===== BODY (squat dome) =====
skin(.42,1); edge(1.4*s);
beginShape();
vertex(-66*s*chub,6*s);
bezierVertex(-70*s*chub,-46*s, -30*s,-64*s, 0,-64*s);
bezierVertex(30*s,-64*s, 70*s*chub,-46*s, 66*s*chub,6*s);
bezierVertex(60*s*chub,40*s, 34*s,52*s, 0,52*s);
bezierVertex(-34*s,52*s, -60*s*chub,40*s, -66*s*chub,6*s);
endShape(CLOSE);
// belly / lighter underside
skin(.72,.4); if(wire){edge(1.1*s);noFill();} ellipse(0,26*s, 78*s*chub, 44*s);

// ===== FRONT ARMS =====
for(const sgn of [-1,1]){ push(); translate(sgn*46*s*chub, 30*s); rotate(sgn*(0.5 - stretch*0.3)); skin(.3,1); edge(1.1*s); ellipse(sgn*8*s, 14*s, 16*s, 34*s*LL);
  skin(.4,.6); const hx=sgn*12*s; beginShape(); vertex(hx,26*s); for(let k=-1;k<=2;k++){ vertex(hx+sgn*(6+k*4)*s, 34*s+Math.abs(k)*2*s);} endShape(); pop(); }

// ===== xray bones overlay =====
if(xray){ stroke(md(H+20,360), 25, 96, 78); strokeWeight(1.6*s); noFill();
  line(0,-40*s,0,44*s); // spine
  for(let r=0;r<4;r++){ const yy=-24*s+r*16*s; line(-4*s,yy, -30*s*chub, yy+6*s); line(4*s,yy, 30*s*chub, yy+6*s); }
  // pulsing heart glow
  noStroke(); fill(md(H+340,360), 70, 95, 30+croak*50); ellipse(-8*s,0, (18+croak*10)*s, (16+croak*8)*s);
  fill(md(H+30,360),20,90,20); ellipse(0,20*s,50*s,34*s); // gut membrane
}

// ===== HEAD / EYES =====
push();
translate(0, -50*s - croak*4*s);
// wide mouth line
if(!wire){ stroke(md(H, 360), lino?80:40, xray?70:16, 60); strokeWeight(2*s); noFill(); arc(0, -2*s, 66*s*chub, 30*s, 0.15, Math.PI-0.15); noStroke(); }
// throat sac (inflates)
skin(.55,.5); const sac=(10+croak*30); ellipse(0, 20*s + croak*10*s, 44*s*chub, sac*s);
// bulging eyes on top
for(const sgn of [-1,1]){ push(); translate(sgn*30*s*chub, -20*s - BUL*6*s);
  skin(.5,1); edge(1.2*s); ellipse(0,0, 34*s*BUL, 36*s*BUL);
  if(!wire){ noStroke(); const blink=(frc(K.t*.27+sgn*.13)>.93)?.15:1;
    fill(toxic?md(H+180,360):md(H+40,360), 90, 96); ellipse(0, 2*s, 22*s*BUL, 24*s*BUL*blink);
    fill(0,0,6); ellipse(0, 4*s, 9*s, 20*s*BUL*blink); // slit pupil
