  else { edge(1.1*s); ellipse(0,2*s, 20*s*BUL, 22*s*BUL); }
pop(); }
pop();

// stipple over toxic body
if(toxic&&S.dot){ push(); blendMode(SCREEN); imageMode(CENTER); image(S.dot, 0, -6*s, 160*s*chub, 150*s); imageMode(CORNER); blendMode(BLEND); pop(); }

if(swamp||xray){ drawingContext.shadowBlur=0; }
